                "Spacer_line12__",
                "Spacer_line13__",
                "Spacer_line14__",
                "Spacer_line15__",
                "Spacer_line17__",
                "Spacer_line18__",
                "Spacer_line19__"
            ];
            deprecatedFields.forEach((field) => {
