																			"options": {
																				"label": "ActionMenu__",
																				"width": "100%",
																				"htmlContent": "<input id=\"onActionLoad\" type=\"hidden\" onclick=\"onActionLoad(event);\">\n<input id=\"enableButton\" type=\"hidden\" onclick=\"enableButton(event);\">\n<div id=\"NavButtons\" class=\"nav-body\">\n    <ul class=\"nav-topbar\">\n        <li class=\"nav-item\">\n            <a class=\"nav-link\" id=\"MoreDetails\" data-package=\"P2P_AP\" onclick=\"MoreDetails()\">_More_Details</a>\n        </li>\n        <li class=\"nav-item-divider action-divider\" data-package=\"P2P_VENDOR\" id=\"EditDivider\" style=\"display:none;\"></li>\n        <li class=\"nav-item\">\n            <a class=\"nav-link\" id=\"Edit\" data-package=\"P2P_VENDOR\" onclick=\"EditAction()\" style=\"display:none;\">_Edit</a>\n        </li>\n        <li class=\"nav-item-divider action-divider\" data-package=\"P2P_VENDOR\" id=\"CloneDivider\" style=\"display:none;\"></li>\n        <li class=\"nav-item\">\n            <a class=\"nav-link\" id=\"Clone\" data-package=\"P2P_VENDOR\" onclick=\"CloneAction()\" style=\"display:none;\">_Clone</a>\n        </li>\n    </ul>\n</div>\n<script>\n    window.postMessage({ eventName: \"onActionLoad\", control: \"ActionMenu__\" }, document.location.origin);\n    var buttonsItems = document.getElementById(\"NavButtons\").getElementsByClassName(\"nav-link\");\n    var dividersItems = document.getElementById(\"NavButtons\").getElementsByClassName(\"nav-item-divider\");\n\tfunction enableButton(evt)\n\t{\n\t\tdocument.getElementById(evt.buttonId + \"Divider\").style.display = \"\";\n\t\tdocument.getElementById(evt.buttonId).style.display = \"\";\n\t}\n    function onActionLoad(evt) {\n        for (var element in evt.tabs) {\n            var elem = document.getElementById(element);\n            if (elem)\n                elem.innerText = evt.tabs[element];\n        }\n        for (var i = 0; i < buttonsItems.length; i++) {\n            var datapackage = buttonsItems[i].getAttribute(\"data-package\");\n            if (!datapackage || !evt.appInstances[datapackage])\n                buttonsItems[i].style.display = \"none\";\n        }\n        for (var i = 0; i < dividersItems.length; i++) {\n            var datapackage = dividersItems[i].getAttribute(\"data-package\");\n            if (!datapackage || !evt.appInstances[datapackage])\n                dividersItems[i].style.display = \"none\";\n        }\n    }\n    function MoreDetails() {\n        ClearTabs();\n        window.postMessage({ eventName: \"MoreDetails\", control: \"ActionMenu__\" }, document.location.origin);\n    }\n    function EditAction()\n    {\n        window.postMessage({ eventName: \"EditAction\", control: \"ActionMenu__\" }, document.location.origin);\n    }\n    function CloneAction()\n    {\n        window.postMessage({ eventName: \"CloneAction\", control: \"ActionMenu__\" }, document.location.origin);\n    }\n</script>",
																				"version": 0
