																	"*": {
																		"NavMenu__": {
																			"type": "HTML",
																			"data": false,
																			"stamp": 32,
																			"options": {
																				"label": "HTML content",
																				"htmlContent": "<input id=\"onLoad\" type=\"hidden\" onclick=\"OnLoad(event);\">\n<input id=\"onPackageLoad\" type=\"hidden\" onclick=\"OnPackageLoad(event);\">\n<input id=\"onChangeTab\" type=\"hidden\" onclick=\"OnChangeTab(event);\">\n<div id=\"NavMenu\" class=\"nav-body\" style=\"\">\n\t<ul class=\"nav-sidebar\">\n\t\t<li class=\"nav-item\">\n\t\t\t<a id=\"overview\" onclick=\"OnClickTab(this.id);\" href=\"#\" class=\"nav-link\">\n\t\t\t\t<span class=\"icon fa fa-home\"></span>\n\t\t\t\t<span id=\"overviewLbl\"/>\n\t\t\t</a>\n\t\t</li>\n\t\t<li class=\"nav-item-divider\"></li>\n\t\t<li class=\"nav-item\">\n\t\t\t<a id=\"invoices\" style=\"display:none\" data-package=\"P2P_AP\" onclick=\"OnClickTab(this.id);\" href=\"#\" class=\"nav-link\">\n\t\t\t\t<span id=\"invoicesLbl\"/>\n\t\t\t</a>\n\t\t</li>\n\t\t<li class=\"nav-item\">\n\t\t\t<a id=\"purchaseOrders\" style=\"display:none\" data-package=\"P2P_PAC\" onclick=\"OnClickTab(this.id);\" href=\"#\" class=\"nav-link\">\n\t\t\t\t<span id=\"purchaseOrdersLbl\"/>\n\t\t\t</a>\n\t\t</li>\n\t\t<li class=\"nav-item\">\n\t\t\t<a id=\"contracts\" style=\"display:none\" data-package=\"P2P_CONTRACT\" onclick=\"OnClickTab(this.id);\" href=\"#\" class=\"nav-link\">\n\t\t\t\t<span id=\"contractsLbl\"/>\n\t\t\t</a>\n\t\t</li>\n\t\t<li class=\"nav-item\">\n\t\t\t<a id=\"vendorRegistrations\" style=\"display:none\" data-package=\"P2P_AP\" onclick=\"OnClickTab(this.id);\" href=\"#\" class=\"nav-link\">\n\t\t\t\t<span id=\"vendorRegistrationsLbl\"/>\n\t\t\t</a>\n\t\t</li>\n\t\t<li class=\"nav-item\">\n\t\t\t<a id=\"relatedDoc\" style=\"display:none\" data-package=\"DD\" onclick=\"OnClickTab(this.id);\" href=\"#\" class=\"nav-link\">\n\t\t\t\t<span id=\"relatedDocLbl\"/>\n\t\t\t</a>\n\t\t</li>\n\t\t<li class=\"nav-item-divider\"></li>\n\t\t<li class=\"nav-item\">\n\t\t\t<a id=\"contacts\" style=\"display:none\" data-package=\"P2P\" onclick=\"OnClickTab(this.id);\" href=\"#\" class=\"nav-link\">\n\t\t\t\t<span class=\"icon fa fa-users\"></span>\n\t\t\t\t<span id=\"contactsLbl\"/>\n\t\t\t</a>\n\t\t</li>\n\t\t<li class=\"nav-item\">\n\t\t\t<a id=\"settings\" style=\"display:none\" data-package=\"P2P\" href=\"#\" onclick=\"OnClickTab(this.id);\"class=\"nav-link\">\n\t\t\t\t<span class=\"icon fa fa-gear\"></span>\n\t\t\t\t<span id=\"settingsLbl\"/>\n\t\t\t</a>\n\t\t</li>\n\t</ul>\n</div>\n<script>\n\twindow.postMessage({eventName: \"onLoad\", control: \"NavMenu__\"}, document.location.origin);\n\tvar tabItems = document.getElementById(\"NavMenu\").getElementsByClassName(\"nav-link\");\n\tfunction OnClickTab(tabID) {\n\t\tClearTabs();\n\n\t\tvar tab = document.getElementById(tabID);\n\t\ttab.className = \"nav-link active\";\n\t\twindow.postMessage({eventName: \"onClick\", control: \"NavMenu__\", args: tab.id}, document.location.origin);\n\t}\n\tfunction OnChangeTab(evt)\n\t{\n\t\tOnClickTab(evt.tabId);\n\t}\n\tfunction OnLoad(evt) {\n\t\tfor (var lbl in evt.tabs)\n\t\t{\n\t\t\tvar elem = document.getElementById(lbl + \"Lbl\");\n\t\t\tif (elem)\n\t\t\t\telem.innerText = evt.tabs[lbl];\n\t\t}\n\t\tfor (var i = 0; i < tabItems.length; i++) {\n\t\t\tvar datapackage = tabItems[i].getAttribute(\"data-package\");\n\t\t\tif (datapackage && evt.appInstances[datapackage])\n\t\t\t\ttabItems[i].style.display = \"inherit\";\n\t\t}\n\t\tvar startMenu = document.getElementById(evt.startMenu);\n\t\tstartMenu.className = \"nav-link active\";\n\t}\n\tfunction ClearTabs() {\n\t\tfor (var i = 0; i < tabItems.length; i++)\n\t\t\ttabItems[i].className = \"nav-link\";\n\t}\n</script>",
																				"width": "100%",
