															"*": {
																"Grid": {
																	"type": "GridLayout",
																	"data": [
																		"fields"
																	],
																	"stamp": 71,
																	"options": {
																		"version": 0,
																		"lines": 2,
																		"columns": 2,
																		"ctrlsPos": {
																			"DisplayedStatusHTML__": {
																				"line": 1,
																				"column": 1
																			},
																			"LabelShowComplianceAlerts__": {
																				"line": 2,
