																	"*": {
																		"DisplayedStatusHTML__": {
																			"type": "HTML",
																			"data": false,
																			"stamp": 72,
																			"options": {
																				"label": "_ComplianceStatus",
																				"htmlContent": "<input id=\"onDisplayWidgetStatus\" type=\"hidden\" onclick=\"onDisplayWidgetStatus(event);\">\n<div class=\"complianceContainer\" id=\"ComplianceContainer\">\n\t<div class=\"headerContainer\">\n\t\t<div id=\"StatusLogo\" class=\"complianceLogowrapper\" onerror=\"onImgError(this);\"></div>\n\t\t<div id=\"AlertIcon\" class=\"fa fa-exclamation-circle alertIcon\" ></div>\n\t</div>\n\t<div class=\"badgeContainer\">\n\t\t<div id=\"DisplayedStatusBadgeValue\" class=\"badge\">\n\t\t\t<a id=\"DisplayedStatusValue\"></a>\n\t\t</div>\n\t\t<span id=\"RefreshButton\" class=\"esk-ifont-rotate-solid custom-action-button\"  onclick=\"onRefresh(this);\"></span>\n\t</div>\n\t<div id=\"ProgressBarContainer\" class=\"progressBarContainer\">\n\t\t<div class=\"cursorContainer\">\n\t\t\t<div id=\"Cursor\"></div>\n\t\t</div>\n\t\t<div id=\"ProgressBar\"></div>\n\t</div>\n</div>\n<script>\n\twindow.postMessage({ eventName: \"onLoad\", control: \"DisplayedStatusHTML__\" }, document.location.origin);\n\n\tfunction onImgError (imgElem) { imgElem.style.display = \"none\"; };\n\n\tfunction onRefresh () {\n\t\twindow.postMessage({ eventName: \"onRefresh\", control: \"DisplayedStatusHTML__\" }, document.location.origin);\n\t}\n\n\tfunction onDisplayWidgetStatus(evt)\n\t{\n\t\tdocument.getElementById(\"DisplayedStatusValue\").innerText = evt.value;\n\n\t\tif (evt.widgetInForm)\n\t\t{\n\t\t\tdocument.getElementById(\"ComplianceContainer\").classList.add(\"widgetInForm\");\n\t\t}\n\t\telse\n\t\t{\n\t\t\tdocument.getElementById(\"ComplianceContainer\").classList.remove(\"widgetInForm\");\n\t\t}\n\n\t\tif (evt.link)\n\t\t{\n\t\t\tdocument.getElementById('DisplayedStatusValue').href = evt.link;\n\t\t\tdocument.getElementById('DisplayedStatusValue').target = \"_blank\";\n\t\t\tdocument.getElementById('DisplayedStatusBadgeValue').classList.add(\"badgeWithLink\");\n\t\t}\n\t\telse\n\t\t{\n\t\t\tdocument.getElementById('DisplayedStatusValue').removeAttribute(\"href\");\n\t\t\tdocument.getElementById('DisplayedStatusBadgeValue').classList.remove(\"badgeWithLink\");\n\t\t}\n\n\t\tif (evt.logoPath)\n\t\t{\n\t\t\tdocument.getElementById(\"StatusLogo\").style = \"background-image: url(\" + evt.logoPath + \");\";\n\t\t}\n\t\telse\n\t\t{\n\t\t\tdocument.getElementById(\"StatusLogo\").style = \"display: none;\";\n\t\t}\n\n\t\tvar root = document.documentElement;\n\t\tif (evt.color && CSS.supports('color', evt.color))\n\t\t{\n\t\t\troot.style.setProperty('--badge-color', evt.color);\n\t\t\troot.style.setProperty('--badge-alt-color', 'white');\n\t\t}\n\t\telse\n\t\t{\n\t\t\troot.style.setProperty('--badge-color', 'white');\n\t\t\troot.style.setProperty('--badge-alt-color', '#008998');\n\t\t}\n\n\t\tif (evt.alert)\n\t\t{\n\t\t\tdocument.getElementById(\"AlertIcon\").style = \"display: block;\";\n\t\t\tdocument.getElementById(\"AlertIcon\").setAttribute('title', evt.tooltip);\n\t\t}\n\t\telse\n\t\t{\n\t\t\tdocument.getElementById(\"AlertIcon\").style = \"display: none;\";\n\t\t}\n\n\t\tif(!evt.widgetInForm && evt.progressBar)\n\t\t{\n\t\t\tdisplayProgressBar(evt.progressBar);\n\t\t}\n\t}\n\n\tfunction displayProgressBar(progressBar)\n\t{\n\t\tvar states = progressBar.states\n\t\tvar position = progressBar.position;\n\n\t\tif (states != null && states.length > 0 && position >=0 && position < states.length)\n\t\t{\n\t\t\tvar progressBarContent = \"\";\n\t\t\tstates.forEach(color => {\n\t\t\t\tprogressBarContent += '<div style=\"background-color: ' + color + '; width:100%;\"></div>';\n\t\t\t});\n\n\t\t\tdocument.getElementById(\"ProgressBar\").innerHTML = progressBarContent;\n\n\t\t\tvar margin = `calc((100%/${states.length*2}) * (${position}/${states.length}*${states.length*2} + 1) - 4px)`;\n\t\t\tdocument.getElementById(\"Cursor\").style.marginLeft = margin;\n\t\t\tdocument.getElementById(\"ProgressBarContainer\").style.display = \"flex\";\n\t\t}\n\t\telse\n\t\t{\n\t\t\tdocument.getElementById(\"ProgressBarContainer\").style.display = \"none\";\n\t\t}\n\t}\n</script>",
																				"css": ":root {\n\t--badge-color: white;\n\t--bagde-alt-color: #008998;\n}\n\n#ComplianceRiskPanel {\n\tflex-basis: 10% !important;\n}\n\n.complianceContainer {\n\tdisplay: flex;\n\tflex-direction: column;\n\twhite-space: normal;\n\twidth: 100%;\n\tjustify-content: space-around;\n\talign-items: center;\n\theight: 220px;\n}\n\n.complianceContainer .headerContainer {\n\tdisplay: flex;\n\tjustify-content: center;\n\talign-items: center;\n}\n\n.complianceContainer .headerContainer .complianceLogowrapper {\n\twidth: 150px;\n\theight: 35px;\n\tmargin: 0;\n\tbackground-size: contain;\n\tbackground-repeat: no-repeat;\n\tbackground-position: center;\n}\n\n.complianceContainer .headerContainer .alertIcon {\n\tfont-size:15px;\n\tmargin-left: 10px;\n\tcolor: rgb(255, 108, 12);\n}\n\n.complianceContainer .badgeContainer {\n\tdisplay: flex;\n\talign-items: center;\n\tmargin-top: 10px;\n}\n\n.complianceContainer .custom-action-button {\n\tdisplay: none;\n\tmargin-right: -30px;\n}\n\n.complianceContainer .badge {\n\tmargin: 0;\n\tborder-style: solid;\n\tborder-radius: 4px;\n\tborder-width: 1px;\n\tdisplay: flex;\n\tjustify-content: center;\n\twidth: auto;\n\tmin-width: 185px;\n\tbackground-color: var(--badge-color);\n\tcolor: var(--badge-alt-color);\n\tborder-color: var(--badge-color);\n}\n\n.complianceContainer .badgeWithLink:hover {\n\tborder-color: var(--badge-color);\n\tbackground-color: white;\n\tcolor: var(--badge-color);\n\tbackground-color: var(--badge-alt-color);\n}\n\n.complianceContainer .badge > a {\n\tfont-size: 20px;\n\tfont-family: Roboto Bold;\n\tline-height: normal;\n\tdisplay: block;\n\ttext-transform: uppercase;\n\ttext-decoration: none;\n\tcolor: inherit;\n\tpadding: 6px;\n\twidth: 100%;\n\ttext-align: center;\n\tcursor: default;\n}\n\n.complianceContainer .badgeWithLink > a {\n\tcursor: pointer;\n}\n\n.complianceContainer .badgeWithLink > a:after{\n\tfont-size: 10px;\n\tcontent: '\\f08e';\n\tfont-family: FontAwesome;\n\tfont-style: normal;\n\tfont-weight: normal;\n\ttext-decoration: inherit;\n\tmargin-left:5px;\n}\n\n.complianceContainer.widgetInForm {\n\tjustify-content: center;\n\theight: unset;\n}\n\n.complianceContainer.widgetInForm .badge {\n\tmin-width: 160px;\n\twidth: auto;\n}\n\n.complianceContainer.widgetInForm .badge > a {\n\tfont-size: inherit;\n\theight: 26px;\n\tline-height: 26px;\n\tpadding: 0;\n}\n\n.complianceContainer.widgetInForm .custom-action-button {\n\tdisplay: block;\n}\n\n.complianceContainer .progressBarContainer {\n\tdisplay: none;\n\tflex-direction: column;\n\twidth: 185px;\n}\n\n.complianceContainer .cursorContainer {\n\ttext-align: left;\n\tline-height: 1;\n\tmargin-bottom: -1px;\n\tz-index: 0;\n}\n\n.complianceContainer #ProgressBar {\n\tdisplay: flex;\n\tflex-direction: row;\n\talign-items: stretch;\n\theight: 10px;\n    overflow: hidden;\n\tborder-radius: 1px;\n}\n\n.complianceContainer #Cursor {\n\tdisplay: inline-block;\n\theight: 0;\n\twidth: 0;\n\tborder-right: 4px solid transparent;\n\tborder-top: 8px solid black;\n\tborder-left: 4px solid transparent;\n\tborder-radius: 0px;\n\tmargin-bottom: 2px;\n}",
																				"width": "100%",
																				"version": 0
																			}
